-- Hawaii 1778: unique units and buildings of the five chiefdoms, cloned from the stock rows at load time (generated by text/build_text.py).
-- Japan's and Ethiopia's uniques are unhooked; Polynesia, Zulu and Carthage keep theirs under Hawaiian names (text only).

-- Olohe (HILO): UNIT_SWORDSMAN
CREATE TEMP TABLE tmp_u AS SELECT * FROM Units WHERE Type = 'UNIT_SWORDSMAN';
UPDATE tmp_u SET ID = (SELECT MAX(ID) + 1 FROM Units), Type = 'UNIT_HI1778_OLOHE', Description = 'TXT_KEY_UNIT_HI1778_OLOHE', Civilopedia = 'TXT_KEY_CIV5_HI1778_OLOHE_TEXT', Strategy = 'TXT_KEY_UNIT_HI1778_OLOHE_STRATEGY', Help = 'TXT_KEY_UNIT_HI1778_OLOHE_HELP', Combat = Combat - 1;

-- Pololu (MAUI): UNIT_SPEARMAN
CREATE TEMP TABLE tmp_u AS SELECT * FROM Units WHERE Type = 'UNIT_SPEARMAN';
UPDATE tmp_u SET ID = (SELECT MAX(ID) + 1 FROM Units), Type = 'UNIT_HI1778_POLOLU', Description = 'TXT_KEY_UNIT_HI1778_POLOLU', Civilopedia = 'TXT_KEY_CIV5_HI1778_POLOLU_TEXT', Strategy = 'TXT_KEY_UNIT_HI1778_POLOLU_STRATEGY', Help = 'TXT_KEY_UNIT_HI1778_POLOLU_HELP', Combat = Combat + 1;

-- Maa Slinger (KAUAI): UNIT_ARCHER
CREATE TEMP TABLE tmp_u AS SELECT * FROM Units WHERE Type = 'UNIT_ARCHER';
UPDATE tmp_u SET ID = (SELECT MAX(ID) + 1 FROM Units), Type = 'UNIT_HI1778_MAA', Description = 'TXT_KEY_UNIT_HI1778_MAA', Civilopedia = 'TXT_KEY_CIV5_HI1778_MAA_TEXT', Strategy = 'TXT_KEY_UNIT_HI1778_MAA_STRATEGY', Help = 'TXT_KEY_UNIT_HI1778_MAA_HELP', Cost = 30;

-- replace the donors' unique units
DELETE FROM Civilization_UnitClassOverrides WHERE CivilizationType = 'CIVILIZATION_JAPAN';
DELETE FROM Civilization_UnitClassOverrides WHERE CivilizationType = 'CIVILIZATION_ETHIOPIA';
DELETE FROM Civilization_UnitClassOverrides WHERE CivilizationType = 'CIVILIZATION_ZULU';

-- Puuhonua (HILO): BUILDING_SHRINE
CREATE TEMP TABLE tmp_b AS SELECT * FROM Buildings WHERE Type = 'BUILDING_SHRINE';
UPDATE tmp_b SET ID = (SELECT MAX(ID) + 1 FROM Buildings), Type = 'BUILDING_HI1778_PUUHONUA', Description = 'TXT_KEY_BUILDING_HI1778_PUUHONUA', Civilopedia = 'TXT_KEY_CIV5_HI1778_PUUHONUA_TEXT', Strategy = 'TXT_KEY_BUILDING_HI1778_PUUHONUA_STRATEGY', Help = 'TXT_KEY_BUILDING_HI1778_PUUHONUA_HELP', Happiness = 1;

-- Loko Ia (OAHU): BUILDING_LIGHTHOUSE
CREATE TEMP TABLE tmp_b AS SELECT * FROM Buildings WHERE Type = 'BUILDING_LIGHTHOUSE';
UPDATE tmp_b SET ID = (SELECT MAX(ID) + 1 FROM Buildings), Type = 'BUILDING_HI1778_LOKOIA', Description = 'TXT_KEY_BUILDING_HI1778_LOKOIA', Civilopedia = 'TXT_KEY_CIV5_HI1778_LOKOIA_TEXT', Strategy = 'TXT_KEY_BUILDING_HI1778_LOKOIA_STRATEGY', Help = 'TXT_KEY_BUILDING_HI1778_LOKOIA_HELP', GoldMaintenance = 0;

-- Loi Kalo (KAUAI): BUILDING_GRANARY
CREATE TEMP TABLE tmp_b AS SELECT * FROM Buildings WHERE Type = 'BUILDING_GRANARY';
UPDATE tmp_b SET ID = (SELECT MAX(ID) + 1 FROM Buildings), Type = 'BUILDING_HI1778_LOIKALO', Description = 'TXT_KEY_BUILDING_HI1778_LOIKALO', Civilopedia = 'TXT_KEY_CIV5_HI1778_LOIKALO_TEXT', Strategy = 'TXT_KEY_BUILDING_HI1778_LOIKALO_STRATEGY', Help = 'TXT_KEY_BUILDING_HI1778_LOIKALO_HELP', Cost = Cost;
UPDATE Building_YieldChanges SET Yield = 3 WHERE BuildingType = 'BUILDING_HI1778_LOIKALO' AND YieldType = 'YIELD_FOOD';

-- replace the donors' unique buildings
DELETE FROM Civilization_BuildingClassOverrides WHERE CivilizationType = 'CIVILIZATION_ETHIOPIA';

-- No horses in the islands: every mounted unit, every unit that needs Horses and the stables move to a technology nobody can research,
-- so that neither the chiefdoms nor the barbarians ever field them.
UPDATE Units SET PrereqTech = 'TECH_ASTRONOMY' WHERE CombatClass = 'UNITCOMBAT_MOUNTED' OR Type IN (SELECT UnitType FROM Unit_ResourceQuantityRequirements WHERE ResourceType = 'RESOURCE_HORSE');
UPDATE Buildings SET PrereqTech = 'TECH_ASTRONOMY' WHERE BuildingClass = 'BUILDINGCLASS_STABLE';
